source.foundation.onto:
project OpenInstitution
  @description "Company identity and shared operating commitments."

actor Operator
  @type organization
  @affiliation internal
  @access authenticated

object Company
  name: string @required
  ceiling: int @required
  @rule Company.ceiling is at least 0

seed Operator
  name: "Ada"

seed Company
  name: "Core", ceiling: 100
